mkdir -p /work/qrypt-aes && cd /work/qrypt-aes && cat > package.json <<'EOF'
{
  "name": "qrypt-aes",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Generate an AES-256 key from Qrypt quantum entropy",
  "engines": { "node": ">=20.12" },
  "scripts": { "start": "qrypt-run qrypt-aes/generate-key.mjs" }
}
EOF
printf '.env\n*.key\nnode_modules/\n' > .gitignore
cat > generate-key.mjs <<'EOF'
// Generate an AES-256 key from Qrypt quantum entropy and verify it with an
// AES-256-GCM round trip. Run via: qrypt-run qrypt-aes/generate-key.mjs
import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";

const ENTROPY_URL = "https://api-eus.qrypt.com/api/v1/quantum-entropy?size=1"; // size is in KiB

process.loadEnvFile(new URL("../.env", import.meta.url));
const token = process.env.QRYPT_API_KEY;
if (!token) throw new Error("QRYPT_API_KEY is not set in .env");

const ERRORS = {
  400: "size out of range (1-512 KiB)",
  401: "missing, malformed or expired auth",
  403: "invalid token or monthly quota exhausted",
  429: "rate limited; wait at least 10s before retrying",
};

async function fetchQuantumEntropy() {
  const res = await fetch(ENTROPY_URL, {
    headers: { Authorization: `Bearer ${token}`, "User-Agent": "qrypt-aes/1.0" },
  });
  if (!res.ok) {
    const hint = ERRORS[res.status] ?? (res.status >= 500 ? "service issue; retry later" : "unexpected error");
    throw new Error(`Qrypt API returned ${res.status}: ${hint}`);
  }
  const { random } = await res.json();
  return Buffer.from(random[0], "base64"); // decode; never use the base64 text as key material
}

const entropy = await fetchQuantumEntropy();
if (entropy.length < 32) throw new Error(`expected >= 32 bytes of entropy, got ${entropy.length}`);
const key = entropy.subarray(0, 32); // AES-256 key

// Verify with an AES-256-GCM encrypt/decrypt round trip using a fresh 12-byte nonce.
const nonce = randomBytes(12);
const plaintext = Buffer.from("hello from quantum entropy");
const cipher = createCipheriv("aes-256-gcm", key, nonce);
const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
const tag = cipher.getAuthTag();
const decipher = createDecipheriv("aes-256-gcm", key, nonce);
decipher.setAuthTag(tag);
const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
if (!decrypted.equals(plaintext)) throw new Error("AES-256-GCM round trip failed");

// Report only non-secret facts about the key; never print or persist the key itself.
const fingerprint = createHash("sha256").update(key).digest("hex").slice(0, 16);
console.log(`Received ${entropy.length} bytes of quantum entropy`);
console.log(`AES-256 key: ${key.length * 8} bits, SHA-256 fingerprint ${fingerprint}…`);
console.log("AES-256-GCM round trip: OK");
EOF
cd /work && qrypt-run qrypt-aes/generate-key.mjs

